import Foundation

public struct PaymentOptionsResponse: Codable {
    var has_available_payment_options: Bool? = false
    var single_checkout_enabled: Bool? = false
    var available_payment_labels: Array<AvailablePayment>? = Array()
    
    init(jsonData: Data) {
        let decoder = JSONDecoder()
        self = try! decoder.decode(PaymentOptionsResponse.self, from: jsonData)
    }
    
    func convertToJson() -> String {
        let jsonData = try! JSONEncoder().encode(self)
        return String(data: jsonData, encoding: .utf8)!
    }
}
